fn solve(word: Vec<char>) -> Vec<char> {
    // Define Sets as arrays for membership checking
    const SET_A: [char; 15] = ['A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z'];
    const SET_B: [char; 11] = ['B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U'];

    // Helper function to check membership in Set A
    fn is_in_set_a(c: char) -> bool {
        SET_A.contains(&c)
    }

    // Helper function to check membership in Set B
    fn is_in_set_b(c: char) -> bool {
        SET_B.contains(&c)
    }

    // Determine which set the first character belongs to
    if word.is_empty() {
        // According to constraints this case doesn't occur, but let's be safe
        return "NO".chars().collect();
    }

    let first_char = word[0];
    let set_a_first = is_in_set_a(first_char);
    let set_b_first = is_in_set_b(first_char);

    // If the first char is in neither set (should not happen), return NO
    if !(set_a_first || set_b_first) {
        return "NO".chars().collect();
    }

    // Check all characters belong in the same set as the first character
    for &c in word.iter().skip(1) {
        if set_a_first && !is_in_set_a(c) {
            return "NO".chars().collect();
        }
        if set_b_first && !is_in_set_b(c) {
            return "NO".chars().collect();
        }
    }

    // If we reach here, all characters belong to the same set
    "YES".chars().collect()
}